 static Map<String,String> seals(Path root)throws Exception{var result=new TreeMap<String,String>();try(var files=Files.walk(root)){for(var path:files.filter(Files::isRegularFile).toList())result.put(root.relativize(path).toString(),HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path))));}return result;}
 static void snapshot(org.springframework.jdbc.core.JdbcTemplate j,Path path,com.fasterxml.jackson.databind.ObjectMapper json)throws Exception {var rows=j.queryForList("SELECT t.id task_id,t.state task_state,t.attempt,t.last_error,t.output_kind,t.output_id,e.id execution_id,e.state execution_state,o.id operation_id,o.state operation_state,o.external_result_id,r.id reservation_id,r.settled_at FROM durable_task t JOIN external_execution e ON e.task_id=t.id JOIN external_operation o ON o.id=e.operation_id LEFT JOIN model_reservation r ON r.execution_id=e.id WHERE t.id=? AND e.id=? AND o.id=?",TASK,EXECUTION,OPERATION);var safe=new ArrayList<Map<String,String>>();for(var row:rows){var copy=new TreeMap<String,String>();row.forEach((k,v)->copy.put(k,v==null?null:v.toString()));safe.add(copy);}Files.writeString(path,json.writeValueAsString(safe));}
